import{_ as e,c as a,o as t,a3 as s}from"./chunks/framework.MI-M1z4O.js";const d=JSON.parse('{"title":"課題管理の重要原則5つ","description":"Jiraを効率的に活用するための重要原則をご紹介します。課題の割り当てルール、必須コメントガイド、ステータス管理のノウハウを通じて、プロジェクトの透明性とチームの生産性を高める方法をご確認ください。チームコラボレーションのためのガイドです。","frontmatter":{"title":"課題管理の重要原則5つ","description":"Jiraを効率的に活用するための重要原則をご紹介します。課題の割り当てルール、必須コメントガイド、ステータス管理のノウハウを通じて、プロジェクトの透明性とチームの生産性を高める方法をご確認ください。チームコラボレーションのためのガイドです。","head":[["meta",{"name":"keywords","content":"Jira, 課題管理, Jiraの使い方, プロジェクト管理, コラボレーションツール, 割り当て原則, コメント記載, ステータス管理, ワークフロー, 生産性向上"}],["meta",{"property":"og:title","content":"課題管理の重要原則5つ | 効果的なプロジェクト管理手法"}],["meta",{"property":"og:description","content":"課題を効率的に活用するための重要原則をご紹介します。課題の割り当てルール、必須コメントガイド、ステータス管理のノウハウを通じて、プロジェクトの透明性とチームの生産性を高める方法をご確認ください。チームコラボレーションのためのガイドです。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/PrinciplesForIssueUsage"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/PrinciplesForIssueUsage"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/PrinciplesForIssueUsage"}]],"sort":6000},"headers":[],"relativePath":"ja/agile/PrinciplesForIssueUsage.md","filePath":"ja/agile/PrinciplesForIssueUsage.md","lastUpdated":1795293539000}'),l={name:"ja/agile/PrinciplesForIssueUsage.md"};function n(o,r,i,g,c,h){return t(),a("div",null,[...r[0]||(r[0]=[s('<h2 id="課題を効果的に活用するための重要原則" tabindex="-1">課題を効果的に活用するための重要原則 <a class="header-anchor" href="#課題を効果的に活用するための重要原則" aria-label="Permalink to “課題を効果的に活用するための重要原則”">​</a></h2><h3 id="_1-割り当て原則" tabindex="-1">1. <strong>割り当て原則</strong> <a class="header-anchor" href="#_1-割り当て原則" aria-label="Permalink to “1. 割り当て原則”">​</a></h3><ul><li><strong>現在の担当者への割り当て</strong>: 課題は、現在実際に作業を進めている担当者に常に割り当てる必要があります。</li><li><strong>割り当て後の即時確認</strong>: 課題が割り当てられたら、担当者は速やかに確認し、作業開始の有無を明示します。</li><li><strong>未割り当ての禁止</strong>: 担当者が指定されていない課題は放置されやすいため、空欄のままにしません。</li></ul><h3 id="_2-コメント作成原則" tabindex="-1">2. <strong>コメント作成原則</strong> <a class="header-anchor" href="#_2-コメント作成原則" aria-label="Permalink to “2. コメント作成原則”">​</a></h3><ul><li><strong>作業完了時のコメント必須</strong>: 作業完了後は、必ず処理結果を記載したコメントを追加します。</li><li><strong>進捗状況の共有</strong>: 特に長期にわたる作業では、適宜進捗状況をコメントで共有します。</li><li><strong>ステータス変更時のコメント</strong>: ステータスを変更する際（例：進行中 → 完了）は、変更理由を明記します。</li><li><strong>無意味なコメントの禁止</strong>: 「確認しました」「進行中です」などの内容のないコメントだけを繰り返さないようにします。</li></ul><h3 id="_3-ステータス管理原則" tabindex="-1">3. <strong>ステータス管理原則</strong> <a class="header-anchor" href="#_3-ステータス管理原則" aria-label="Permalink to “3. ステータス管理原則”">​</a></h3><ul><li><strong>リアルタイムなステータス更新</strong>: 作業状況に応じてステータスを即座に更新します。</li><li><strong>明確なステータス定義</strong>: チームごとに各ステータスの意味を明確に定義し、一貫して運用します。</li><li><strong>放置状態の禁止</strong>: 「進行中」ステータスのまま長期間放置しないようにします。</li></ul><h3 id="_4-課題作成原則" tabindex="-1">4. <strong>課題作成原則</strong> <a class="header-anchor" href="#_4-課題作成原則" aria-label="Permalink to “4. 課題作成原則”">​</a></h3><ul><li><strong>明確なタイトル</strong>: 何を行う課題なのかを一目で把握できるタイトルを付けます。</li><li><strong>詳細な説明</strong>: 再現手順、期待される結果、実際の結果を含む詳細な内容を記述します。</li><li><strong>必須フィールドの入力</strong>: 優先度、見積もり所要時間、コンポーネントなどの必須フィールドを必ず入力します。</li><li><strong>曖昧な表現の禁止</strong>: 「問題あり」「直してください」などの不明確な表現は使用しません。</li></ul><h3 id="_5-ワークフロー遵守原則" tabindex="-1">5. <strong>ワークフロー遵守原則</strong> <a class="header-anchor" href="#_5-ワークフロー遵守原則" aria-label="Permalink to “5. ワークフロー遵守原則”">​</a></h3><ul><li><strong>定義されたワークフローの遵守</strong>: チームで定めたワークフローを厳格に遵守します。</li><li><strong>レビュープロセスの遵守</strong>: コードレビューやQA工程など、必要な手順を省略しません。</li><li><strong>一貫したプロセス</strong>: すべてのチームメンバーが同一のプロセスに従って作業を進めます。</li></ul><h2 id="例-理想的な課題処理フロー" tabindex="-1">例：理想的な課題処理フロー <a class="header-anchor" href="#例-理想的な課題処理フロー" aria-label="Permalink to “例：理想的な課題処理フロー”">​</a></h2><ol><li><strong>課題作成</strong> → 担当者の割り当て + 優先度の設定</li><li><strong>作業開始</strong> → ステータスを「進行中」へ変更 + 開始コメントの記載</li><li><strong>進行中</strong> → 中間進捗のコメント作成（必要時）</li><li><strong>作業完了</strong> → ステータスを「完了」へ変更 + <strong>詳細な処理結果コメントの記載</strong></li><li><strong>レビューが必要な場合</strong> → ステータスを「レビュー中」へ変更 + レビュアーの割り当て</li></ol>',13)])])}const m=e(l,[["render",n]]);export{d as __pageData,m as default};
